extra_css:
.lia-slide__content .h1::after { content: ''; display: block; width: 8rem; height: 0.4rem; margin-top: 0.6rem; background: #ffde59; }
.lia-quote { border-left: 0.4rem solid #ffde59; }
.lia-header { border-bottom: 0.3rem solid #ffde59; }
/* honeycomb gallery: hexagon-cut images, tiles without the black backdrop */
.lia-gallery .lia-figure__media { background: transparent; }
.lia-gallery img { clip-path: polygon(25% 5%, 75% 5%, 100% 50%, 75% 95%, 25% 95%, 0% 50%); }
/* retro offset shadow on section titles */
.lia-slide__content :is(h1, .h1) { text-shadow: 0.25rem 0.25rem 0 #ffde59; }
:root.lia-variant-dark .lia-slide__content :is(h1, .h1) { text-shadow: 0.25rem 0.25rem 0 rgba(255, 222, 89, 0.45); }
